import Foundation

extension TabManager {
    /// Retires only untouched conversation-only rows generated by the earlier
    /// Home sidebar. Their conversations remain in the in-pane list; renamed,
    /// pinned, split, and mixed-content workspaces remain ordinary workspaces.
    func removeLegacyChiefConversationWorkspaces(in home: Workspace) {
        guard let groupID = home.groupId,
              let homePanel = home.panels.values.compactMap({ $0 as? ChiefPanel }).first(where: \.isHome)
        else { return }
        let legacy = tabs.filter { workspace in
            workspace.id != home.id && workspace.groupId == groupID
                && !workspace.isPinned && workspace.effectiveCustomTitleSource == .auto
                && workspace.customTitle != nil && workspace.panels.count == 1
                && workspace.bonsplitController.allPaneIds.count == 1
                && workspace.panels.values.first is ChiefPanel
        }
        let selected = legacy.first { $0.id == selectedTabId }
        if let panel = selected?.panels.values.first as? ChiefPanel {
            homePanel.conversationID = panel.conversationID
            selectWorkspace(home)
        }
        for workspace in legacy { closeWorkspace(workspace, recordHistory: false) }
    }
}
